        name, facts = coffee_name(bag, bag.coffee_id, bag.coffee_freetext)
        if c := store.coffee(bag.coffee_id):
            facts = c.get("roaster_name") or ""  # the origin is under From the catalog
        z = tz(request)
        return page(
            request,
            "coffee.html",
