  <div class="top"><span class="meta">{{ now.strftime("%A, %B ") ~ now.day }}</span></div>
  <h1 class="serif title mt8">Nothing on the grinder yet</h1>
  {% if grinder and basket %}
  <p class="body">Type the coffee you’re about to open. The app looks for it among the
    coffees US roasters list online, and every shot is saved with it.</p>
  {% else %}
  <p class="body">Add your grinder and basket first. Then type the coffee you’re about to open.</p>
  {% endif %}
  <div class="spacer"></div>
  <div class="dock">
    {% if not grinder %}<a class="btn primary" href="/setup/gear/new?kind=grinder&amp;next=/">Add your grinder</a>
    {% elif not basket %}<a class="btn primary" href="/setup/gear/new?kind=basket&amp;next=/">Add your basket</a>
    {% else %}<a class="btn primary" href="/bag/new">Type the coffee</a>{% endif %}
  </div>
{% endblock %}
{% block nav %}{{ nav('today') }}{% endblock %}

