      await p.goto(`${base}/shot/first`);
      const [h, m] = (await p.textContent("h1")).match(/(\d{1,2}):(\d{2})$/).slice(1).map(Number);
      await ctx.close();
      return h * 60 + m;
    };
    assert.equal(((await clockIn("Asia/Kolkata")) - (await clockIn("UTC")) + 1440) % 1440, 330);

