@@ -469,3 +469,30 @@ class Store:
         if not (prev and prev.item == bag):
             self._commit(self.bags, bag.bag_id, bag, "bags")
         return bag, matches
+
+    def _open_bag(self, user_id: str, bag_id: str) -> Rec:
+        prev = self._owned(self.bags, bag_id, user_id)
+        if prev is None or prev.deleted:
+            raise NotFound(bag_id)
+        return prev
+
+    def finish_bag(self, user_id: str, bag_id: str, on: date) -> bool:
+        """Finish: the bag again as a new record with finished_on set, never a delete, like a retraction.
+        Finishing a finished bag writes nothing and keeps the day it was first finished (an outbox resend)."""
+        prev = self._open_bag(user_id, bag_id)
+        if prev.item.finished_on:
+            return False
+        if on > datetime.now(UTC).date() + timedelta(days=1):  # a day's grace, as for roast dates
+            raise Invalid("That finish date is in the future. Check the phone's date.")
+        if prev.item.opened_on and on < prev.item.opened_on:
+            on = prev.item.opened_on  # a phone's clock behind the bag's own: finished the day it was opened
+        self._commit(self.bags, bag_id, prev.item.model_copy(update={"finished_on": on}), "bags")
+        return True
+
+    def reopen_bag(self, user_id: str, bag_id: str) -> bool:
+        """Undo a finish: the bag again without finished_on, as a new record. An open bag writes nothing."""
+        prev = self._open_bag(user_id, bag_id)
+        if not prev.item.finished_on:
+            return False
+        self._commit(self.bags, bag_id, prev.item.model_copy(update={"finished_on": None}), "bags")
+        return True
